-- OpsCore v0.11.50: operational jobs, service-line cutover, invoice payment ledger and reconciliation.
CREATE TABLE IF NOT EXISTS operational_jobs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, queue_name TEXT NOT NULL CHECK(queue_name IN ('support','billing','incident','general')), job_type TEXT NOT NULL, entity_type TEXT, entity_id TEXT, payload_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL CHECK(status IN ('queued','processing','completed','failed','dead_letter')), attempts BIGINT NOT NULL DEFAULT 0, max_attempts BIGINT NOT NULL DEFAULT 5 CHECK(max_attempts BETWEEN 1 AND 20), available_at TEXT NOT NULL, lease_until TEXT, last_error TEXT, result_json TEXT, created_by TEXT REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT);
CREATE INDEX IF NOT EXISTS idx_operational_jobs_queue ON operational_jobs(organization_id,queue_name,status,available_at,created_at);
CREATE INDEX IF NOT EXISTS idx_operational_jobs_lease ON operational_jobs(status,lease_until);
CREATE TABLE IF NOT EXISTS service_lines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, code TEXT NOT NULL, name TEXT NOT NULL, network_ref TEXT NOT NULL, active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,code));
CREATE TABLE IF NOT EXISTS customer_service_lines (organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, line_id TEXT NOT NULL REFERENCES service_lines(id) ON DELETE RESTRICT, assigned_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(organization_id,customer_id));
CREATE INDEX IF NOT EXISTS idx_customer_service_lines_line ON customer_service_lines(organization_id,line_id);
CREATE TABLE IF NOT EXISTS line_migration_jobs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, from_line_id TEXT NOT NULL REFERENCES service_lines(id) ON DELETE RESTRICT, to_line_id TEXT NOT NULL REFERENCES service_lines(id) ON DELETE RESTRICT, status TEXT NOT NULL CHECK(status IN ('preflight','ready','running','completed','rolled_back','failed')), preflight_hash TEXT NOT NULL, before_hash TEXT, after_hash TEXT, rollback_json TEXT, error_code TEXT, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS uq_line_migration_active ON line_migration_jobs(organization_id,customer_id) WHERE status IN ('preflight','ready','running');
CREATE INDEX IF NOT EXISTS idx_line_migration_org_status ON line_migration_jobs(organization_id,status,created_at);
CREATE TABLE IF NOT EXISTS payment_reconciliation_runs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, provider TEXT NOT NULL CHECK(provider IN ('local','stripe')), scope_json TEXT NOT NULL, matched_count BIGINT NOT NULL, mismatch_count BIGINT NOT NULL, unmatched_count BIGINT NOT NULL, report_json TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('completed','failed')), created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_recon_org_created ON payment_reconciliation_runs(organization_id,created_at);
CREATE TABLE IF NOT EXISTS invoice_payments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, amount NUMERIC(14,2) NOT NULL CHECK(amount > 0), source TEXT NOT NULL CHECK(source IN ('local_manual','stripe')), provider_reference TEXT, idempotency_key TEXT, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(organization_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_invoice_payments_org_invoice ON invoice_payments(organization_id,invoice_id,created_at);
